import https from 'https';

const URL = 'https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_110m_admin_0_countries.geojson';

const COUNTRIES = {
  DEU: 'DE',
  CZE: 'CZ',
  SVK: 'SK',
  HUN: 'HU',
  SVN: 'SI',
  ITA: 'IT',
  CHE: 'CH',
  LIE: 'LI',
  HRV: 'HR',
};

// Projection formulas
function projectX(lon) {
  return (lon - 9.5009) / 7.6623 * 612.94;
}

function projectY(lat) {
  return (49.0153 - lat) / 2.6440 * 313.55;
}

// Clipping bounds - expand well beyond the Austria viewbox to show neighbors
const CLIP_MIN_X = -400;
const CLIP_MAX_X = 1100;
const CLIP_MIN_Y = -400;
const CLIP_MAX_Y = 800;

function fetchJSON(url) {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(e);
        }
      });
      res.on('error', reject);
    }).on('error', reject);
  });
}

function ringToPath(ring) {
  const projected = ring.map(([lon, lat]) => {
    const x = projectX(lon);
    const y = projectY(lat);
    return [x, y];
  });

  // Build path string
  const parts = projected.map(([x, y], i) => {
    const rx = Math.round(x * 100) / 100;
    const ry = Math.round(y * 100) / 100;
    if (i === 0) return `M${rx},${ry}`;
    return `L${rx},${ry}`;
  });
  parts.push('Z');
  return { path: parts.join(' '), projected };
}

function computeCentroid(allProjected) {
  let sumX = 0, sumY = 0, count = 0;
  for (const ring of allProjected) {
    for (const [x, y] of ring) {
      sumX += x;
      sumY += y;
      count++;
    }
  }
  return {
    x: Math.round((sumX / count) * 100) / 100,
    y: Math.round((sumY / count) * 100) / 100,
  };
}

async function main() {
  console.error('Fetching GeoJSON...');
  const geojson = await fetchJSON(URL);
  console.error(`Loaded ${geojson.features.length} features`);

  const results = {};

  for (const feature of geojson.features) {
    const iso3 = feature.properties.ISO_A3 || feature.properties.ADM0_A3;
    const code = COUNTRIES[iso3];
    if (!code) continue;

    const geometry = feature.geometry;
    let polygons = [];

    if (geometry.type === 'Polygon') {
      polygons = [geometry.coordinates];
    } else if (geometry.type === 'MultiPolygon') {
      polygons = geometry.coordinates;
    }

    const allPaths = [];
    const allProjected = [];

    for (const polygon of polygons) {
      // polygon[0] is the outer ring, rest are holes
      for (let ri = 0; ri < polygon.length; ri++) {
        const ring = polygon[ri];
        const { path, projected } = ringToPath(ring);
        allPaths.push(path);
        if (ri === 0) allProjected.push(projected); // only outer rings for centroid
      }
    }

    const d = allPaths.join(' ');
    const centroid = computeCentroid(allProjected);

    results[code] = {
      d,
      labelX: centroid.x,
      labelY: centroid.y,
    };

    console.error(`  ${code} (${iso3}): ${polygons.length} polygon(s), centroid=(${centroid.x}, ${centroid.y})`);
  }

  // Check for missing countries
  for (const [iso3, code] of Object.entries(COUNTRIES)) {
    if (!results[code]) {
      console.error(`  WARNING: ${code} (${iso3}) not found in GeoJSON!`);
      // Try alternative property lookups
      for (const feature of geojson.features) {
        const name = feature.properties.NAME;
        const iso2 = feature.properties.ISO_A2;
        if (iso2 === code || (code === 'LI' && name === 'Liechtenstein')) {
          console.error(`    Found via alternative lookup: NAME=${name}, ISO_A2=${iso2}, ISO_A3=${feature.properties.ISO_A3}, ADM0_A3=${feature.properties.ADM0_A3}`);
        }
      }
    }
  }

  // Output TypeScript
  console.log('const neighborPaths: Record<string, { d: string; labelX: number; labelY: number }> = {');
  for (const [code, data] of Object.entries(results)) {
    console.log(`  ${code}: {`);
    console.log(`    d: "${data.d}",`);
    console.log(`    labelX: ${data.labelX},`);
    console.log(`    labelY: ${data.labelY},`);
    console.log(`  },`);
  }
  console.log('};');
}

main().catch(err => {
  console.error('Error:', err);
  process.exit(1);
});

